package main

import (
	"fmt"
	"os"
	"os/exec"
	"syscall"

	"github.com/kyoh86/richgo/internal/richgo"
)

func main() {
	if len(os.Args) > 1 && os.Args[1] == "testfilter" {
		// Handle testfilter mode
		richgo.FilterStdin(os.Args[2:])
		return
	}

	// For other commands, run go with richgo interception
	cmd := exec.Command("go", os.Args[1:]...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr

	err := cmd.Run()
	if err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			os.Exit(exitErr.ExitCode())
		}
		os.Exit(1)
	}
}
EOF

