package style

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

type Style struct {
	Hide      bool   `yaml:"hide"`
	Bold      bool   `yaml:"bold"`
	Faint     bool   `yaml:"faint"`
	Italic    bool   `yaml:"italic"`
	Underline bool   `yaml:"underline"`
	BlinkSlow bool   `yaml:"blinkSlow"`
	BlinkRapid bool  `yaml:"blinkRapid"`
	Inverse   bool   `yaml:"inverse"`
	Conceal   bool   `yaml:"conceal"`
	CrossOut  bool   `yaml:"crossOut"`
	Frame     bool   `yaml:"frame"`
	Encircle  bool   `yaml:"encircle"`
	Overline  bool   `yaml:"overline"`
	Foreground string `yaml:"foreground"`
	Background string `yaml:"background"`
}

const (
	reset = "\033[0m"
)

func (s *Style) Apply(text string) string {
	if s == nil || s.Hide {
		return text
	}

	codes := []string{}

	// Add text attributes
	if s.Bold {
		codes = append(codes, "1")
	}
	if s.Faint {
		codes = append(codes, "2")
	}
	if s.Italic {
		codes = append(codes, "3")
	}
	if s.Underline {
		codes = append(codes, "4")
	}
	if s.BlinkSlow {
		codes = append(codes, "5")
	}
	if s.BlinkRapid {
		codes = append(codes, "6")
	}
	if s.Inverse {
		codes = append(codes, "7")
	}
	if s.Conceal {
		codes = append(codes, "8")
	}
	if s.CrossOut {
		codes = append(codes, "9")
	}
	if s.Frame {
		codes = append(codes, "51")
	}
	if s.Encircle {
		codes = append(codes, "52")
	}
	if s.Overline {
		codes = append(codes, "53")
	}

	// Add foreground color
	if s.Foreground != "" {
		code := parseColorCode(s.Foreground, true)
		if code != "" {
			codes = append(codes, code)
		}
	}

	// Add background color
	if s.Background != "" {
		code := parseColorCode(s.Background, false)
		if code != "" {
			codes = append(codes, code)
		}
	}

	if len(codes) == 0 {
		return text
	}

	codeStr := strings.Join(codes, ";")
	return fmt.Sprintf("\033[%sm%s\033[0m", codeStr, text)
}

func parseColorCode(color string, foreground bool) string {
	color = strings.ToLower(strings.TrimSpace(color))

	// Named colors
	namedColors := map[string]int{
		"black":       30,
		"red":         31,
		"green":       32,
		"yellow":      33,
		"blue":        34,
		"magenta":     35,
		"cyan":        36,
		"white":       37,
		"lightblack":  90,
		"lightgray":   90,
		"lightred":    91,
		"lightgreen":  92,
		"lightyellow": 93,
		"lightblue":   94,
		"lightmagenta": 95,
		"lightcyan":   96,
		"lightwhite":  97,
	}

	// For background colors, add 10 to the code
	if !foreground {
		color = strings.TrimPrefix(color, "light")
		if code, ok := namedColors[color]; ok {
			return strconv.Itoa(code + 10)
		}
		if code, ok := namedColors["light"+color]; ok {
			return strconv.Itoa(code + 10 - 90 + 100)
		}
	}

	// Check named color
	if code, ok := namedColors[color]; ok {
		return strconv.Itoa(code)
	}

	// Handle rgb format: rgb(r,g,b) or rgb(0xrr,0xgg,0xbb)
	if strings.HasPrefix(color, "rgb(") {
		return parseRGBColor(color, foreground)
	}

	// Handle hex format: #xxxxxx
	if strings.HasPrefix(color, "#") {
		return parseHexColor(color, foreground)
	}

	return ""
}

func parseRGBColor(color string, foreground bool) string {
	// Extract numbers from "rgb(r,g,b)"
	re := regexp.MustCompile(`rgb\((.*?)\)`)
	matches := re.FindStringSubmatch(color)
	if len(matches) < 2 {
		return ""
	}

	parts := strings.Split(matches[1], ",")
	if len(parts) != 3 {
		return ""
	}

	var r, g, b int
	for i, part := range parts {
		part = strings.TrimSpace(part)
		// Handle hex values like 0xFF
		if strings.HasPrefix(part, "0x") || strings.HasPrefix(part, "0X") {
			val, err := strconv.ParseInt(part, 0, 32)
			if err != nil {
				return ""
			}
			if i == 0 {
				r = int(val)
			} else if i == 1 {
				g = int(val)
			} else {
				b = int(val)
			}
		} else {
			// Decimal values
			val, err := strconv.Atoi(part)
			if err != nil {
				return ""
			}
			if i == 0 {
				r = val
			} else if i == 1 {
				g = val
			} else {
				b = val
			}
		}
	}

	if foreground {
		return fmt.Sprintf("38;2;%d;%d;%d", r, g, b)
	} else {
		return fmt.Sprintf("48;2;%d;%d;%d", r, g, b)
	}
}

func parseHexColor(color string, foreground bool) string {
	// Remove # and parse as hex
	hex := strings.TrimPrefix(color, "#")
	if len(hex) != 6 {
		return ""
	}

	r, _ := strconv.ParseInt(hex[0:2], 16, 32)
	g, _ := strconv.ParseInt(hex[2:4], 16, 32)
	b, _ := strconv.ParseInt(hex[4:6], 16, 32)

	if foreground {
		return fmt.Sprintf("38;2;%d;%d;%d", r, g, b)
	} else {
		return fmt.Sprintf("48;2;%d;%d;%d", r, g, b)
	}
}
EOF

