package config

import (
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"

	"github.com/kyoh86/richgo/internal/style"
)

type Config struct {
	LabelType          string          `yaml:"labelType"`
	LeaveTestPrefix    bool            `yaml:"leaveTestPrefix"`
	BuildStyle         *style.Style    `yaml:"buildStyle"`
	StartStyle         *style.Style    `yaml:"startStyle"`
	PassStyle          *style.Style    `yaml:"passStyle"`
	FailStyle          *style.Style    `yaml:"failStyle"`
	SkipStyle          *style.Style    `yaml:"skipStyle"`
	FileStyle          *style.Style    `yaml:"fileStyle"`
	LineStyle          *style.Style    `yaml:"lineStyle"`
	PassPackageStyle   *style.Style    `yaml:"passPackageStyle"`
	FailPackageStyle   *style.Style    `yaml:"failPackageStyle"`
	CoverThreshold     int             `yaml:"coverThreshold"`
	CoveredStyle       *style.Style    `yaml:"coveredStyle"`
	UncoveredStyle     *style.Style    `yaml:"uncoveredStyle"`
	Removals           []string        `yaml:"removals"`
}

func LoadConfig() *Config {
	cfg := GetDefaultConfig()

	// Load from environment variable check
	if os.Getenv("RICHGO_LOCAL") == "1" {
		// Only load from current working directory
		if path, err := findConfigFile("."); err == nil {
			loadConfigFile(path, cfg)
		}
	} else {
		// Try to load from multiple paths
		searchPaths := getConfigSearchPaths()
		for _, path := range searchPaths {
			if configFile := findFirstConfigFile(path); configFile != "" {
				loadConfigFile(configFile, cfg)
				break
			}
		}
	}

	return cfg
}

func GetDefaultConfig() *Config {
	return &Config{
		LabelType:       "long",
		LeaveTestPrefix: false,
		BuildStyle: &style.Style{
			Bold:       true,
			Foreground: "yellow",
		},
		StartStyle: &style.Style{
			Foreground: "lightBlack",
		},
		PassStyle: &style.Style{
			Foreground: "green",
		},
		FailStyle: &style.Style{
			Bold:       true,
			Foreground: "red",
		},
		SkipStyle: &style.Style{
			Foreground: "lightBlack",
		},
		PassPackageStyle: &style.Style{
			Foreground: "green",
			Hide:       true,
		},
		FailPackageStyle: &style.Style{
			Bold:       true,
			Foreground: "red",
			Hide:       true,
		},
		FileStyle: &style.Style{
			Foreground: "cyan",
		},
		LineStyle: &style.Style{
			Foreground: "magenta",
		},
		CoverThreshold: 50,
		CoveredStyle: &style.Style{
			Foreground: "green",
		},
		UncoveredStyle: &style.Style{
			Bold:       true,
			Foreground: "yellow",
		},
	}
}

func getConfigSearchPaths() []string {
	paths := []string{}

	// Current working directory
	cwd, _ := os.Getwd()
	paths = append(paths, cwd)

	// GOPATH
	if gopath := os.Getenv("GOPATH"); gopath != "" {
		paths = append(paths, gopath)
	}

	// GOROOT
	if goroot := os.Getenv("GOROOT"); goroot != "" {
		paths = append(paths, goroot)
	}

	// Home directory
	if home, err := os.UserHomeDir(); err == nil {
		paths = append(paths, home)
	}

	return paths
}

func findFirstConfigFile(dir string) string {
	patterns := []string{".richstyle", ".richstyle.yaml", ".richstyle.yml"}
	for _, pattern := range patterns {
		path := filepath.Join(dir, pattern)
		if _, err := os.Stat(path); err == nil {
			return path
		}
	}
	return ""
}

func findConfigFile(dir string) (string, error) {
	patterns := []string{".richstyle", ".richstyle.yaml", ".richstyle.yml"}
	for _, pattern := range patterns {
		path := filepath.Join(dir, pattern)
		if _, err := os.Stat(path); err == nil {
			return path, nil
		}
	}
	return "", fmt.Errorf("no config file found in %s", dir)
}

func loadConfigFile(path string, cfg *Config) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}

	// Simple YAML parser
	lines := strings.Split(string(data), "\n")
	parseYAML(lines, cfg)

	return nil
}

func parseYAML(lines []string, cfg *Config) {
	var currentStyle *style.Style
	var currentStyleName string

	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		// Parse top-level keys
		if strings.HasPrefix(line, "labelType:") {
			cfg.LabelType = strings.TrimSpace(strings.TrimPrefix(line, "labelType:"))
		} else if strings.HasPrefix(line, "leaveTestPrefix:") {
			val := strings.TrimSpace(strings.TrimPrefix(line, "leaveTestPrefix:"))
			cfg.LeaveTestPrefix = val == "true"
		} else if strings.HasPrefix(line, "coverThreshold:") {
			val := strings.TrimSpace(strings.TrimPrefix(line, "coverThreshold:"))
			cfg.CoverThreshold, _ = strconv.Atoi(val)
		}

		// Parse style sections
		if strings.HasSuffix(line, "Style:") {
			currentStyleName = strings.TrimSuffix(line, "Style:")
			currentStyle = &style.Style{}
		}

		// Parse style properties
		if currentStyle != nil && strings.Contains(line, ":") {
			key := strings.TrimSpace(strings.Split(line, ":")[0])
			val := strings.TrimSpace(strings.Split(line, ":")[1])

			switch key {
			case "bold":
				currentStyle.Bold = val == "true"
			case "faint":
				currentStyle.Faint = val == "true"
			case "italic":
				currentStyle.Italic = val == "true"
			case "underline":
				currentStyle.Underline = val == "true"
			case "blinkSlow":
				currentStyle.BlinkSlow = val == "true"
			case "blinkRapid":
				currentStyle.BlinkRapid = val == "true"
			case "inverse":
				currentStyle.Inverse = val == "true"
			case "conceal":
				currentStyle.Conceal = val == "true"
			case "crossOut":
				currentStyle.CrossOut = val == "true"
			case "frame":
				currentStyle.Frame = val == "true"
			case "encircle":
				currentStyle.Encircle = val == "true"
			case "overline":
				currentStyle.Overline = val == "true"
			case "hide":
				currentStyle.Hide = val == "true"
			case "foreground":
				currentStyle.Foreground = val
			case "background":
				currentStyle.Background = val
			}

			// When we encounter a new top-level key or style, save the current one
			if !strings.HasSuffix(line, "Style:") && (strings.HasPrefix(line, "  ") || strings.HasPrefix(line, "\t")) == false {
				assignStyle(cfg, currentStyleName, currentStyle)
				currentStyle = nil
			}
		}
	}

	if currentStyle != nil {
		assignStyle(cfg, currentStyleName, currentStyle)
	}
}

func assignStyle(cfg *Config, styleName string, st *style.Style) {
	switch styleName {
	case "build":
		cfg.BuildStyle = st
	case "start":
		cfg.StartStyle = st
	case "pass":
		cfg.PassStyle = st
	case "fail":
		cfg.FailStyle = st
	case "skip":
		cfg.SkipStyle = st
	case "file":
		cfg.FileStyle = st
	case "line":
		cfg.LineStyle = st
	case "passPackage":
		cfg.PassPackageStyle = st
	case "failPackage":
		cfg.FailPackageStyle = st
	case "covered":
		cfg.CoveredStyle = st
	case "uncovered":
		cfg.UncoveredStyle = st
	}
}
