	}

	// Parse YAML
	parseYAMLLines(strings.Split(string(data), "\n"), cfg)

	return nil
}

func parseYAMLLines(lines []string, cfg *Config) {
	var currentStyleName string
	var currentStyle *style.Style

	for i, line := range lines {
		line = strings.TrimRight(line, " \t")
		indent := getIndentLevel(line)
		trimmed := strings.TrimSpace(line)

		// Skip empty lines and comments
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}

		// Must have a colon to be valid
		if !strings.Contains(trimmed, ":") {
			continue
		}

		parts := strings.SplitN(trimmed, ":", 2)
		key := strings.TrimSpace(parts[0])
		val := strings.TrimSpace(parts[1])

		// Top-level properties
		if indent == 0 {
			// Save any previous style
			if currentStyle != nil {
				assignStyle(cfg, currentStyleName, currentStyle)
			}

			if val == "" {
				// This is a section header (e.g., "buildStyle:")
				currentStyleName = key
				currentStyle = &style.Style{}
			} else {
				// Top-level value
				switch key {
				case "labelType":
					cfg.LabelType = val
				case "leaveTestPrefix":
					cfg.LeaveTestPrefix = val == "true"
				case "coverThreshold":
					if v, err := strconv.Atoi(val); err == nil {
