					}
				}
			}
		} else if indent == 2 || indent == 4 {
			// Style property
			if currentStyle != nil {
				parseStyleProperty(key, val, currentStyle)
			}
		}
	}

	// Save the last style if any
	if currentStyle != nil {
		assignStyle(cfg, currentStyleName, currentStyle)
	}
}

func getIndentLevel(line string) int {
	spaces := 0
	for _, ch := range line {
		if ch == ' ' {
			spaces++
		} else if ch == '\t' {
			spaces += 2 // Treat tab as 2 spaces
		} else {
			break
		}
	}
	return spaces
}

func parseStyleProperty(key, val string, st *style.Style) {
	switch key {
	case "bold":
		st.Bold = val == "true"
	case "faint":
