				case "leaveTestPrefix":
					cfg.LeaveTestPrefix = unquote(val) == "true"
				case "coverThreshold":
					if v, err := strconv.Atoi(unquote(val)); err == nil {
						cfg.CoverThreshold = v
					}
				}
			}
		} else if indent == 2 || indent == 4 {
			// Style property
			if currentStyle != nil {
				parseStyleProperty(key, unquote(val), currentStyle)
			}
		}
	}

	// Save the last style if any
	if currentStyle != nil {
		assignStyle(cfg, currentStyleName, currentStyle)
	}
