func getIndentLevel(line string) int {
	spaces := 0
	for _, ch := range line {
		if ch == ' ' {
			spaces++
		} else if ch == '\t' {
			spaces += 2 // Treat tab as 2 spaces
		} else {
			break
		}
	}
	return spaces
}

func unquote(s string) string {
	// Remove surrounding quotes if present
	if len(s) >= 2 && ((s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '\'' && s[len(s)-1] == '\'')) {
		return s[1 : len(s)-1]
	}
	return s
}

func parseStyleProperty(key, val string, st *style.Style) {
	switch key {
	case "bold":
