package richgo

import (
	"bufio"
	"fmt"
	"os"
	"regexp"
	"strings"

	"github.com/kyoh86/richgo/internal/config"
	"github.com/kyoh86/richgo/internal/style"
)

type LineContext struct {
	lastType string
}

var globalCfg *config.Config
var lineCtx = &LineContext{}
var removalRegexes []*regexp.Regexp

func FilterStdin(args []string) {
	globalCfg = config.LoadConfig()

	// Compile removal patterns
	for _, pattern := range globalCfg.Removals {
		if rx, err := regexp.Compile(pattern); err == nil {
			removalRegexes = append(removalRegexes, rx)
		}
	}

	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		line := scanner.Text()

		// Check if line should be removed
		if shouldRemoveLine(line) {
			continue
		}

		formatted := formatLine(line, globalCfg)
		fmt.Println(formatted)
	}
}

func shouldRemoveLine(line string) bool {
	for _, rx := range removalRegexes {
		if rx.MatchString(line) {
			return true
		}
	}
	return false
}

func formatLine(line string, cfg *config.Config) string {
	// Parse line and determine its type
	lineType := parseLineType(line)

	// Update context
	switch lineType {
	case "start", "pass", "fail", "skip":
		lineCtx.lastType = lineType
	}

	switch lineType {
	case "start":
		return formatStartLine(line, cfg)
	case "pass":
		return formatPassLine(line, cfg)
	case "fail":
		return formatFailLine(line, cfg)
	case "skip":
		return formatSkipLine(line, cfg)
	case "build":
		return formatBuildLine(line, cfg)
	case "passPackage":
		return formatPassPackageLine(line, cfg)
	case "failPackage":
		return formatFailPackageLine(line, cfg)
	case "errorLine":
		return formatErrorLine(line, cfg)
	case "line":
		return formatLineLine(line, cfg)
	case "cover":
		return formatCoverLine(line, cfg)
	default:
		return line
	}
}

func parseLineType(line string) string {
	trimmed := strings.TrimSpace(line)

	// Check for START
	if strings.HasPrefix(trimmed, "=== RUN") {
		return "start"
	}

	// Check for PASS
	if strings.HasPrefix(trimmed, "--- PASS:") {
		return "pass"
	}

	// Check for FAIL
	if strings.HasPrefix(trimmed, "--- FAIL:") {
		return "fail"
	}

	// Check for SKIP
	if strings.HasPrefix(trimmed, "--- SKIP:") {
		return "skip"
	}

	// Check for package result lines
	if strings.HasPrefix(trimmed, "ok\t") {
		return "passPackage"
	}

	if strings.HasPrefix(trimmed, "FAIL\t") {
		return "failPackage"
	}

	if trimmed == "PASS" {
		return "passPackage"
	}

	if trimmed == "FAIL" {
		return "failPackage"
	}

	// Check for indented file:line references (error messages)
	if strings.HasPrefix(line, "    ") && isFileLinePattern(trimmed) {
		return "errorLine"
	}

	// Check for file:line references
	if isFileLine(line) {
		return "line"
	}

	return "unknown"
}

func isFileLinePattern(line string) bool {
	matched, _ := regexp.MatchString(`\S+\.go:\d+:`, line)
	return matched
}

func isFileLine(line string) bool {
	// Matches lines like "    main_test.go:10: message"
	matched, _ := regexp.MatchString(`^\s+\S+\.go:\d+:`, line)
	return matched
}

func formatStartLine(line string, cfg *config.Config) string {
	// Extract test name from "=== RUN   TestExample"
	testName := extractTestName(line, cfg)
	label := getLabel("START", cfg.LabelType)
	return applyStyle(label, testName, cfg.StartStyle, cfg)
}

func formatPassLine(line string, cfg *config.Config) string {
	// Extract test name and time from "--- PASS: TestExample (0.001s)"
	testName, time := extractTestInfo(line, cfg)
	content := fmt.Sprintf("%s %s", testName, time)
	label := getLabel("PASS", cfg.LabelType)
	return applyStyle(label, content, cfg.PassStyle, cfg)
}

func formatFailLine(line string, cfg *config.Config) string {
	// Extract test name and time from "--- FAIL: TestFail (0.002s)"
	testName, time := extractTestInfo(line, cfg)
	content := fmt.Sprintf("%s %s", testName, time)
	label := getLabel("FAIL", cfg.LabelType)
	return applyStyle(label, content, cfg.FailStyle, cfg)
}

func formatSkipLine(line string, cfg *config.Config) string {
	// Extract test name and time from "--- SKIP: TestSkip (0.001s)"
	testName, time := extractTestInfo(line, cfg)
	content := fmt.Sprintf("%s %s", testName, time)
	label := getLabel("SKIP", cfg.LabelType)
	return applyStyle(label, content, cfg.SkipStyle, cfg)
}

func formatBuildLine(line string, cfg *config.Config) string {
	label := getLabel("BUILD", cfg.LabelType)
	return applyStyle(label, line, cfg.BuildStyle, cfg)
}

func formatPassPackageLine(line string, cfg *config.Config) string {
	if cfg.PassPackageStyle.Hide {
		return ""
	}
	label := getLabel("PASS", cfg.LabelType)
	return applyStyle(label, line, cfg.PassPackageStyle, cfg)
}

func formatFailPackageLine(line string, cfg *config.Config) string {
	if cfg.FailPackageStyle.Hide {
		return ""
	}
	label := getLabel("FAIL", cfg.LabelType)
	return applyStyle(label, line, cfg.FailPackageStyle, cfg)
}

func formatErrorLine(line string, cfg *config.Config) string {
	// Format indented error lines with file:line highlighting
	// Format: "    filename.go:line: message"

	indent := getIndent(line)
	content := strings.TrimLeft(line, " \t")

	// Determine the style based on last test result
	var testStyle *style.Style
	switch lineCtx.lastType {
	case "fail":
		testStyle = cfg.FailStyle
	case "pass":
		testStyle = cfg.PassStyle
	case "skip":
		testStyle = cfg.SkipStyle
	default:
		testStyle = cfg.LineStyle
	}

	// If we're colorizing, parse and color the file:line part
	if shouldColorize() {
		// Parse file:line:message
		parts := strings.SplitN(content, ": ", 2)
		if len(parts) == 2 {
			fileLinePart := parts[0]
			message := parts[1]

			// Parse file:line
			fileLineParts := strings.Split(fileLinePart, ":")
			if len(fileLineParts) >= 2 {
				filename := fileLineParts[0]
				lineNum := fileLineParts[1]

				// Build styled output - format is indent + "     | " + file + ":" + line + ": " + message
				var output string
				if cfg.LabelType == "none" {
					output = fmt.Sprintf("%s%s%s: %s",
						indent,
						testStyle.Apply(filename),
						cfg.LineStyle.Apply(":"+lineNum),
						testStyle.Apply(message))
				} else {
					output = fmt.Sprintf("%s     | %s%s: %s",
						indent,
						testStyle.Apply(filename),
						cfg.LineStyle.Apply(":"+lineNum),
						testStyle.Apply(message))
				}

				return output
			}
		}
	}

	// Non-colorized output
	if cfg.LabelType != "none" {
		return fmt.Sprintf("%s     | %s", indent, content)
	}
	return line
}

func formatLineLine(line string, cfg *config.Config) string {
	label := getLabel("LINE", cfg.LabelType)
	return applyStyle(label, line, cfg.LineStyle, cfg)
}

func formatCoverLine(line string, cfg *config.Config) string {
	label := getLabel("COVER", cfg.LabelType)
	return applyStyle(label, line, cfg.CoveredStyle, cfg)
}

func getIndent(line string) string {
	for i, ch := range line {
		if ch != ' ' && ch != '\t' {
			return line[:i]
		}
	}
	return ""
}

func extractTestName(line string, cfg *config.Config) string {
	// Extract from "=== RUN   TestExample"
	parts := strings.Fields(line)
	if len(parts) >= 3 {
		name := parts[2]
		if !cfg.LeaveTestPrefix && strings.HasPrefix(name, "Test") {
			return strings.TrimPrefix(name, "Test")
		}
		return name
	}
	return ""
}

func extractTestInfo(line string, cfg *config.Config) (string, string) {
	// Extract from "--- PASS: TestExample (0.001s)"
	// Format: --- TYPE: TestName (time)
	parts := strings.Split(line, ": ")
	if len(parts) < 2 {
		return "", ""
	}

	rest := parts[1]
	// Find the time in parentheses
	timeStart := strings.LastIndex(rest, "(")
	timePart := ""
	testPart := rest

	if timeStart != -1 {
		timeEnd := strings.LastIndex(rest, ")")
		if timeEnd > timeStart {
			timePart = rest[timeStart : timeEnd+1]
			testPart = strings.TrimSpace(rest[:timeStart])
		}
	}

	if !cfg.LeaveTestPrefix && strings.HasPrefix(testPart, "Test") {
		testPart = strings.TrimPrefix(testPart, "Test")
	}

	return testPart, timePart
}

func getLabel(labelType string, labelTypeConfig string) string {
	switch labelTypeConfig {
	case "long":
		return labelType
	case "short":
		switch labelType {
		case "START":
			return ">"
		case "PASS":
			return "o"
		case "FAIL":
			return "x"
		case "SKIP":
			return "-"
		case "BUILD":
			return "!!"
		case "LINE":
			return ""
		default:
			return ""
		}
	case "none":
		return ""
	default:
		return labelType
	}
}

func applyStyle(label, content string, st *style.Style, cfg *config.Config) string {
	if !shouldColorize() {
		if label == "" {
			return content
		}
		return fmt.Sprintf("%s| %s", label, content)
	}

	// Build output with styling
	output := ""
	if label != "" {
		output = fmt.Sprintf("%s| %s", label, content)
	} else {
		output = content
	}

	// Apply ANSI codes
	return st.Apply(output)
}

func shouldColorize() bool {
	if os.Getenv("RICHGO_FORCE_COLOR") == "1" {
		return true
	}

	// Check if stdout is a TTY
	return isTTY(os.Stdout.Fd())
}

func isTTY(fd uintptr) bool {
	// This is a placeholder - will implement platform-specific check
	return false
}
