	case "passPackage":
		return formatPassPackageLine(line, cfg)
	case "failPackage":
		return formatFailPackageLine(line, cfg)
	case "errorLine":
		return formatErrorLine(line, cfg)
	case "line":
		return formatLineLine(line, cfg)
	case "cover":
		return formatCoverLine(line, cfg)
	default:
		return line
	}
}

func parseLineType(line string) string {
	trimmed := strings.TrimSpace(line)

	// Check for START
	if strings.HasPrefix(trimmed, "=== RUN") {
		return "start"
	}

	// Check for PASS
	if strings.HasPrefix(trimmed, "--- PASS:") {
		return "pass"
	}

	// Check for FAIL
	if strings.HasPrefix(trimmed, "--- FAIL:") {
		return "fail"
	}

	// Check for SKIP
	if strings.HasPrefix(trimmed, "--- SKIP:") {
		return "skip"
	}

	// Check for package result lines
	if strings.HasPrefix(trimmed, "ok\t") {
		return "passPackage"
	}

	if strings.HasPrefix(trimmed, "FAIL\t") {
		return "failPackage"
	}

	if trimmed == "PASS" {
		return "passPackage"
	}

	if trimmed == "FAIL" {
		return "failPackage"
	}

	// Check for indented file:line references (error messages)
	if strings.HasPrefix(line, "    ") && isFileLinePattern(trimmed) {
		return "errorLine"
	}

	// Check for file:line references
	if isFileLine(line) {
		return "line"
	}

