		}
	}

	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		line := scanner.Text()

		// Check if line should be removed
		if shouldRemoveLine(line) {
			continue
		}

		// Process the line
		processLine(line, globalCfg)
	}

	// Flush any remaining buffer
	flushBuffer(globalCfg)
}

func processLine(line string, cfg *config.Config) {
	lineType := parseLineType(line)

	// If this is a result line (pass/fail/skip/package), flush the buffer first
	switch lineType {
	case "pass", "fail", "skip", "passPackage", "failPackage":
		flushBuffer(cfg)
		lineCtx.lastType = lineType
		formatted := formatLine(line, cfg)
		fmt.Println(formatted)
	case "start":
		flushBuffer(cfg)
		lineCtx.lastType = lineType
		formatted := formatLine(line, cfg)
		fmt.Println(formatted)
	default:
		// Buffer other lines
		lineCtx.buffer = append(lineCtx.buffer, line)
	}
}

func flushBuffer(cfg *config.Config) {
	for _, bufferedLine := range lineCtx.buffer {
		formatted := formatLine(bufferedLine, cfg)
		if formatted != "" {
			fmt.Println(formatted)
		}
	}
	lineCtx.buffer = []string{}
}

func shouldRemoveLine(line string) bool {
	for _, rx := range removalRegexes {
		if rx.MatchString(line) {
			return true
		}
	}
	return false
}

func formatLine(line string, cfg *config.Config) string {
	// Parse line and determine its type
	lineType := parseLineType(line)

	switch lineType {
	case "start":
		return formatStartLine(line, cfg)
	case "pass":
		return formatPassLine(line, cfg)
	case "fail":
		return formatFailLine(line, cfg)
	case "skip":
