	parts := strings.Split(line, ": ")
	if len(parts) < 2 {
		return "", ""
	}

	rest := parts[1]
	// Find the time in parentheses
	timeStart := strings.LastIndex(rest, "(")
	timePart := ""
	testPart := rest

	if timeStart != -1 {
		timeEnd := strings.LastIndex(rest, ")")
		if timeEnd > timeStart {
			timePart = rest[timeStart : timeEnd+1]
			testPart = strings.TrimSpace(rest[:timeStart])
		}
	}

	if !cfg.LeaveTestPrefix && strings.HasPrefix(testPart, "Test") {
		testPart = strings.TrimPrefix(testPart, "Test")
	}

	return testPart, timePart
